    STAT_EN[`pen.${t2}`] = `${TYPE_EN[t2]} penetration`;
    STAT_EN[`convert.${t2}`] = `of physical damage converted to ${TYPE_EN[t2]}`;
    STAT_EN[`addMin.${t2}`] = `minimum added ${TYPE_EN[t2]} damage`;
    STAT_EN[`addMax.${t2}`] = `maximum added ${TYPE_EN[t2]} damage`;
